import React, { useState, useEffect, useCallback } from "react";
import AdvancedAuth from "./AdvancedAuth";
import Header from "./layout/Header/Header";
import { updateUserProfile } from "../api/profileApi";
import PhoneInput from 'react-phone-number-input';
import { isValidPhoneNumber } from 'libphonenumber-js';
import { useToast } from "../hooks/useToast";
import ToastContainer from "./ui/ToastContainer";
import "../styles/Account.css";
import "../styles/AccountDetails.css";
import "../styles/OrderHistory.css";
import "../styles/AddressModal.css";
import 'react-phone-number-input/style.css';

const Account = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState("details");
  const [csrfToken, setCsrfToken] = useState(null);
  const [showAddressModal, setShowAddressModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [addresses, setAddresses] = useState([]);
  const { showSuccess, showError } = useToast();
  const [addressForm, setAddressForm] = useState({
    city: '',
    address_line1: '',
    address_line2: '',
    postal_code: '',
    address_type: 'shipping'
  });
  const [userForm, setUserForm] = useState({
    first_name: '',
    last_name: '',
    phone: '',
    email: ''
  });

  // В Django DRF Token Auth нет механизма обновления токена, поэтому просто проверяем валидность текущего
  const refreshAccessToken = async () => {
    try {
      // Проверяем текущий токен через запрос к профилю
      const token = localStorage.getItem("token");
      if (!token) return null;
      
      const response = await fetch("/api/accounts/users/me/", {
        method: "GET",
        headers: {
          "Authorization": `Token ${token}`,
        },
        credentials: "include"
      });

      if (response.ok) {
        return token;
      } else {
        localStorage.removeItem("token");
        setIsLoggedIn(false);
        setUser(null);
        return null;
      }
    } catch (error) {
      console.error("Ошибка обновления токена:", error);
      return null;
    }
  };

  const fetchWithAuth = async (url, options = {}) => {
    let token = localStorage.getItem("token");

    const makeRequest = async (authToken) => {
      return fetch(url, {
        ...options,
        headers: {
          ...options.headers,
          Authorization: `Token ${authToken}`,
          "Content-Type": "application/json"
        },
        credentials: "include"
      });
    };

    let response = await makeRequest(token);

    if (response.status === 401) {
      token = await refreshAccessToken();
      if (token) {
        response = await makeRequest(token);
      }
    }

    return response;
  };

  const fetchUserProfile = useCallback(async () => {
    try {
      const response = await fetchWithAuth("/api/accounts/users/me/");

      if (response.ok) {
        const data = await response.json();
        setUser(data);
        setIsLoggedIn(true);
      } else {
        localStorage.removeItem("token");
        setIsLoggedIn(false);
        setUser(null);
      }
    } catch (error) {
      console.error("Ошибка получения профиля:", error);
      localStorage.removeItem("token");
      setIsLoggedIn(false);
      setUser(null);
    }
  }, []);

  useEffect(() => {
    const initializeAuth = async () => {
      try {
        // Получаем CSRF токен из cookie (Django автоматически устанавливает его)
        const cookies = document.cookie.split(';');
        for (let cookie of cookies) {
          const [name, value] = cookie.trim().split('=');
          if (name === 'csrftoken') {
            setCsrfToken(value);
            break;
          }
        }

        // Проверяем токен доступа
        const token = localStorage.getItem("token");
        if (token) {
          await fetchUserProfile();
        }
      } catch (error) {
        console.error("Ошибка инициализации:", error);
      } finally {
        setLoading(false);
      }
    };

    initializeAuth();
  }, [fetchUserProfile]);



  // Обработка входа
  const handleLogin = async (loginData) => {
    try {
      const response = await fetch("/api/accounts/users/login/", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          ...(csrfToken ? { "X-CSRFToken": csrfToken } : {})
        },
        credentials: "include",
        body: JSON.stringify(loginData)
      });

      const data = await response.json();

      if (response.ok) {
        localStorage.setItem("token", data.token);
        setUser(data.user);
        setIsLoggedIn(true);
      } else {
        throw new Error(data.detail || data.message || "Ошибка входа");
      }
    } catch (error) {
      throw error;
    }
  };

  // Обработка регистрации
  const handleRegister = async (registrationData) => {
    try {
      const response = await fetch("/api/accounts/users/", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          ...(csrfToken ? { "X-CSRFToken": csrfToken } : {})
        },
        credentials: "include",
        body: JSON.stringify(registrationData)
      });

      const data = await response.json();

      if (response.ok) {
        localStorage.setItem("token", data.token);
        setUser(data.user);
        setIsLoggedIn(true);
      } else {
        // Создаем ошибку с полной информацией ответа сервера
        const error = new Error(data.detail || data.message || "Ошибка регистрации");
        error.response = { data };
        throw error;
      }
    } catch (error) {
      throw error;
    }
  };

  // Обработка Google входа
  const handleGoogleLogin = async () => {
    try {
      // Проверяем доступность Google API
      if (!window.google || !window.google.accounts) {
        throw new Error("Google Sign-In API не загружен");
      }

      // Создаем промис для обработки ответа
      return new Promise((resolve, reject) => {
        window.google.accounts.id.initialize({
          client_id:
            "1089807285342-lbpiogofotk3ftnvilenr0d0emvsfpnp.apps.googleusercontent.com",
          callback: async (response) => {
            try {
              console.log("Google response:", response); // Отладка

              const res = await fetch("/api/accounts/users/google-login/", {
                method: "POST",
                headers: {
                  "Content-Type": "application/json",
                  ...(csrfToken ? { "X-CSRFToken": csrfToken } : {})
                },
                credentials: "include",
                body: JSON.stringify({ credential: response.credential })
              });

              const data = await res.json();
              console.log("Backend response:", data); // Отладка

              if (res.ok) {
                localStorage.setItem("token", data.token);
                setUser(data.user);
                setIsLoggedIn(true);
                resolve(data);
              } else {
                reject(new Error(data.message || "Ошибка входа через Google"));
              }
            } catch (error) {
              console.error("Error in Google callback:", error);
              reject(error);
            }
          },
          auto_select: false,
          cancel_on_tap_outside: true,
          use_fedcm_for_prompt: false,
          ux_mode: "popup" // Используем popup режим
        });

        // Показываем popup для входа
        window.google.accounts.id.prompt((notification) => {
          console.log("Google prompt notification:", notification);
          if (notification.isNotDisplayed() || notification.isSkippedMoment()) {
            // Если One Tap не показался, используем popup
            window.google.accounts.oauth2
              .initTokenClient({
                client_id:
                  "1089807285342-lbpiogofotk3ftnvilenr0d0emvsfpnp.apps.googleusercontent.com",
                scope: "email profile",
                callback: async (tokenResponse) => {
                  try {
                    // Получаем информацию о пользователе
                    const userInfoResponse = await fetch(
                      `https://www.googleapis.com/oauth2/v2/userinfo?access_token=${tokenResponse.access_token}`
                    );
                    const userInfo = await userInfoResponse.json();

                    // Отправляем данные на бэкенд
                    const res = await fetch("/api/auth/google-login", {
                      method: "POST",
                      headers: {
                        "Content-Type": "application/json",
                        ...(csrfToken ? { "X-CSRF-Token": csrfToken } : {})
                      },
                      credentials: "include",
                      body: JSON.stringify({
                        userInfo: userInfo,
                        access_token: tokenResponse.access_token
                      })
                    });

                    const data = await res.json();

                    if (res.ok) {
                      localStorage.setItem("access_token", data.access_token);
                      setUser(data.user);
                      setIsLoggedIn(true);
                      resolve(data);
                    } else {
                      reject(
                        new Error(data.message || "Ошибка входа через Google")
                      );
                    }
                  } catch (error) {
                    reject(error);
                  }
                }
              })
              .requestAccessToken();
          }
        });
      });
    } catch (error) {
      console.error("Google login error:", error);
      throw error;
    }
  };

  const handleLogout = async () => {
    try {
      // Отправляем запрос на выход из системы
      await fetch("/api/accounts/users/logout/", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          ...(csrfToken ? { "X-CSRFToken": csrfToken } : {}),
          "Authorization": `Token ${localStorage.getItem("token")}`
        },
        credentials: "include"
      });
    } catch (error) {
      console.error("Ошибка при выходе из системы:", error);
    } finally {
      // Удаляем токен из localStorage и сбрасываем состояние
      localStorage.removeItem("token");
      setIsLoggedIn(false);
      setUser(null);
    }
  };

  // Функции для работы с адресами
  // В Django нет отдельного API для адресов, адрес хранится в профиле пользователя
  const fetchAddresses = async () => {
    try {
      // Получаем профиль пользователя, который содержит адрес
      const response = await fetchWithAuth('/api/accounts/users/me/');
      if (response.ok) {
        const userData = await response.json();
        // Если у пользователя есть адрес, создаем объект адреса из данных профиля
        if (userData.address) {
          setAddresses([{
            id: 1, // Используем фиктивный ID, так как это единственный адрес
            first_name: userData.first_name,
            last_name: userData.last_name,
            address_line1: userData.address,
            city: '',
            postal_code: '',
            country: 'Россия'
          }]);
        } else {
          setAddresses([]);
        }
      }
    } catch (error) {
      console.error('Ошибка загрузки адресов:', error);
    }
  };

  const handleAddressSubmit = async (e) => {
    e.preventDefault();
    try {
      // Получаем текущий профиль пользователя
      const profileResponse = await fetchWithAuth('/api/accounts/users/me/');
      if (!profileResponse.ok) {
        throw new Error('Не удалось получить профиль пользователя');
      }
      
      const userData = await profileResponse.json();
      
      // Обновляем профиль пользователя с новым адресом
      const response = await fetchWithAuth('/api/accounts/users/me/', {
        method: 'PATCH',
        body: JSON.stringify({
          address: addressForm.address_line1 + 
                  (addressForm.address_line2 ? ', ' + addressForm.address_line2 : '') +
                  (addressForm.city ? ', ' + addressForm.city : '') +
                  (addressForm.postal_code ? ', ' + addressForm.postal_code : '')
        })
      });
      
      if (response.ok) {
        setShowAddressModal(false);
        setAddressForm({
          city: '',
          address_line1: '',
          address_line2: '',
          postal_code: '',
          address_type: 'shipping'
        });
        fetchAddresses(); // Обновляем список адресов
      } else {
        const errorData = await response.json();
        console.error('Ошибка обновления адреса:', errorData);
      }
    } catch (error) {
      console.error('Ошибка:', error);
    }
  };

  // Функция для удаления адреса
  const handleDeleteAddress = async (addressId) => {
    if (!window.confirm('Вы уверены, что хотите удалить этот адрес?')) {
      return;
    }

    try {
      // В Django адрес хранится в профиле пользователя, поэтому мы просто очищаем поле address
      const response = await fetchWithAuth('/api/accounts/users/me/', {
        method: 'PATCH',
        body: JSON.stringify({
          address: ''
        })
      });

      if (response.ok) {
        alert('Адрес успешно удален!');
        fetchAddresses(); // Обновляем список адресов
      } else {
        const errorData = await response.json();
        alert(`Ошибка: ${errorData.message || 'Не удалось удалить адрес'}`);
      }
    } catch (error) {
      console.error('Ошибка при удалении адреса:', error);
      alert('Произошла ошибка при удалении адреса');
    }
  };

  const handleInputChange = (e) => {
    const { name, value, type, checked } = e.target;
    setAddressForm(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value
    }));
  };

  // Загружаем адреса при входе пользователя
  useEffect(() => {
    if (isLoggedIn && user) {
      fetchAddresses();
      // Инициализируем форму редактирования данными пользователя
      setUserForm({
        first_name: user.first_name || '',
        last_name: user.last_name || '',
        phone: user.phone || '',
        email: user.email || ''
      });
    }
  }, [isLoggedIn, user]);

  if (loading) {
    return (
      <>
        <Header isHome={false} />
        <div className="account-figma-root">
          <div className="account-figma-content centered-auth">
            <div className="account-figma-loading">Загрузка...</div>
          </div>
        </div>
      </>
    );
  }

  // Если пользователь авторизован, показываем профиль
  if (isLoggedIn && user) {
    return (
      <>
        <Header isHome={false} />
        <ToastContainer position="top-center" />
        <div className="account-figma-root">
          <div className="account-figma-sidebar account-sidebar-fixed">
            <div className="account-figma-menu">
              <div
                className={
                  "account-figma-menu-item account-menu-item-nowrap" +
                  (activeTab === "details"
                    ? " account-figma-menu-item-active"
                    : "")
                }
                onClick={() => setActiveTab("details")}
              >
                ACCOUNT DETAILS
              </div>
              <div
                className={
                  "account-figma-menu-item account-menu-item-nowrap" +
                  (activeTab === "orders"
                    ? " account-figma-menu-item-active"
                    : "")
                }
                onClick={() => setActiveTab("orders")}
              >
                ORDER HISTORY
              </div>
              <div
                className="account-figma-menu-item account-menu-item-nowrap"
                onClick={handleLogout}
              >
                LOGOUT
              </div>
            </div>
          </div>
          <div className="account-figma-content">
            {activeTab === "details" ? (
              <div className="account-details-container">
                <div className="account-details-block">
                  <div className="account-details-block-header">
                    <span>ОСНОВНАЯ ИНФОРМАЦИЯ</span>
                    <div className="account-details-block-sub"></div>
                  </div>
                  <div className="account-details-block-value">
                    {user.first_name} {user.last_name}
                    <br />
                    {user.email}
                    {user.phone && (
                      <>
                        <br />
                        {user.phone}
                      </>
                    )}
                  </div>
                  <button 
                    className="account-details-add-btn"
                    onClick={() => setShowEditModal(true)}
                  >
                    ИЗМЕНИТЬ
                  </button>
                </div>
                <div className="account-details-block">
                  <div className="account-details-block-header">
                    <span>АДРЕС</span>
                  </div>
                  <div className="account-details-block-value">
                    {addresses.length > 0 ? (
                      addresses.map((address, index) => (
                        <div key={address.id || index} className="address-item">
                          <div className="address-info">
                            <p><strong>{address.first_name} {address.last_name}</strong></p>
                            <p>{address.address_line1}
                              {address.address_line2 && `, ${address.address_line2}`}
                              {address.city && `, ${address.city}`}
                            </p>
                            {address.postal_code && <p>Индекс: {address.postal_code}</p>}
                            
                          </div>
                          <button 
                            className="delete-address-btn"
                            onClick={() => handleDeleteAddress(address.id)}
                            title="Удалить адрес"
                          >
                            ✕
                          </button>
                        </div>
                      ))
                    ) : (
                      "—"
                    )}
                  </div>
                  <button 
                    className="account-details-add-btn"
                    onClick={() => setShowAddressModal(true)}
                  >
                    ДОБАВИТЬ
                  </button>
                </div>
              </div>
            ) : (
              <div className="account-figma-orders-block">
                <div className="account-figma-orders-header">
                  <div className="account-figma-orders-col">ORDER NO.</div>
                  <div className="account-figma-orders-col">DATE</div>
                  <div className="account-figma-orders-col">PAYMENT STATUS</div>
                  <div className="account-figma-orders-col">
                    FULFILLMENT STATUS
                  </div>
                  <div className="account-figma-orders-col">TOTAL</div>
                </div>
                <div className="account-figma-orders-empty">Нет заказов</div>
              </div>
            )}
          </div>
        </div>
        
        {/* Модальное окно редактирования данных пользователя */}
        {showEditModal && (
          <div className="modal-overlay" onClick={() => setShowEditModal(false)}>
            <div className="modal-content" onClick={(e) => e.stopPropagation()}>
              <div className="modal-header">
                <h3>Редактировать данные</h3>
                <button 
                  className="modal-close"
                  onClick={() => setShowEditModal(false)}
                >
                  ×
                </button>
              </div>
              <form onSubmit={async (e) => {
                e.preventDefault();
                
                // Валидация телефонного номера
                if (userForm.phone && !isValidPhoneNumber(userForm.phone)) {
                  showError('Некорректный формат российского номера телефона. Пример: +79372172203');
                  return;
                }
                
                try {
                  await updateUserProfile(userForm);
                  // Обновляем данные пользователя в состоянии
                  setUser(prev => ({
                    ...prev,
                    ...userForm
                  }));
                  setShowEditModal(false);
                  showSuccess('Данные успешно обновлены!');
                } catch (error) {
                  console.error('Ошибка обновления данных:', error);
                  showError('Произошла ошибка при обновлении данных: ' + (error.response?.data?.message || 'Неизвестная ошибка'));
                }
              }} className="address-form">
                
                <div className="form-group">
                  <label>Имя*</label>
                  <input
                    type="text"
                    name="first_name"
                    value={userForm.first_name}
                    onChange={(e) => setUserForm(prev => ({ ...prev, first_name: e.target.value }))}
                    required
                  />
                </div>
                
                <div className="form-group">
                  <label>Фамилия*</label>
                  <input
                    type="text"
                    name="last_name"
                    value={userForm.last_name}
                    onChange={(e) => setUserForm(prev => ({ ...prev, last_name: e.target.value }))}
                    required
                  />
                </div>
                

                
                <div className="form-group">
                  <label>Email*</label>
                  <input
                    type="email"
                    name="email"
                    value={userForm.email}
                    onChange={(e) => setUserForm(prev => ({ ...prev, email: e.target.value }))}
                    required
                  />
                </div>
                
                <div className="form-group">
                  <label>Телефон</label>
                  <PhoneInput
                    international
                    defaultCountry="RU"
                    name="phone"
                    value={userForm.phone}
                    onChange={(value) => setUserForm(prev => ({ ...prev, phone: value }))}
                    placeholder="+7 (999) 123-45-67"
                  />
                </div>
                
                <div className="form-actions">
                  <button type="button" onClick={() => setShowEditModal(false)} className="btn-cancel">
                    Отмена
                  </button>
                  <button type="submit" className="btn-submit">
                    Сохранить
                  </button>
                </div>
              </form>
            </div>
          </div>
        )}
        
        {/* Модальное окно добавления адреса */}
        {showAddressModal && (
          <div className="modal-overlay" onClick={() => setShowAddressModal(false)}>
            <div className="modal-content" onClick={(e) => e.stopPropagation()}>
              <div className="modal-header">
                <h3>Добавить адрес</h3>
                <button 
                  className="modal-close"
                  onClick={() => setShowAddressModal(false)}
                >
                  ×
                </button>
              </div>
              <form onSubmit={handleAddressSubmit} className="address-form">
                
                <div className="form-group">
                  <label>Город*</label>
                  <input
                    type="text"
                    name="city"
                    value={addressForm.city}
                    onChange={handleInputChange}
                    required
                  />
                </div>
                
                <div className="form-group">
                  <label>Улица, дом*</label>
                  <input
                    type="text"
                    name="address_line1"
                    value={addressForm.address_line1}
                    onChange={handleInputChange}
                    placeholder="Улица, дом"
                    required
                  />
                </div>
                
                <div className="form-group">
                  <label>Квартира</label>
                  <input
                    type="text"
                    name="address_line2"
                    value={addressForm.address_line2}
                    onChange={handleInputChange}
                    placeholder="Номер квартиры"
                  />
                </div>
                
                <div className="form-group">
                  <label>Почтовый индекс*</label>
                  <input
                    type="text"
                    name="postal_code"
                    value={addressForm.postal_code}
                    onChange={handleInputChange}
                    required
                  />
                </div>
                
                <div className="form-actions">
                  <button type="button" onClick={() => setShowAddressModal(false)} className="btn-cancel">
                    Отмена
                  </button>
                  <button type="submit" className="btn-submit">
                    Добавить адрес
                  </button>
                  <button type="button" className="btn-pickup" onClick={() => {
                    // Здесь будет интеграция с картами для выбора пункта выдачи
                    alert('Интеграция с картами будет добавлена позже');
                  }}>
                    Добавить пункт выдачи
                  </button>
                </div>
              </form>
            </div>
          </div>
        )}
      </>
    );
  }

  // Если пользователь не авторизован, показываем новую систему аутентификации
  return (
    <>
      <Header isHome={false} />
      <div className="account-auth-wrapper">
        <AdvancedAuth
          onLogin={handleLogin}
          onRegister={handleRegister}
          onGoogleLogin={handleGoogleLogin}
        />
      </div>
    </>
  );
};

export default Account;
